sys_ux_data_broker_transform.script:
function transform(input) {  
    var output = [];  
    var propertyName = 'sam.integration'; // Update with actual property name  
    var propertyValue = gs.getProperty(propertyName);  

    if (!propertyValue) {  
        gs.error('System property "' + propertyName + '" is empty or not set.');  
        return output;  
    }  

    try {  
        var integrationData = JSON.parse(propertyValue);  

        for (var i = 0; i < integrationData.length; i++) {  
            var title = integrationData[i].title;  
            var taskArray = [];  

            var taskGr = new GlideRecord('samp_sp_vb_task');  
            taskGr.addQuery('short_description', 'Integration Task for ' + title);
			taskGr.addEncodedQuery('stateNOT IN2,-5,3,7');  
            taskGr.query();  

            while (taskGr.next()) {  
                taskArray.push({  
                    sys_id: taskGr.getValue('sys_id'),  
                    short_description: taskGr.getValue('short_description'),  
                    description: taskGr.getValue('description'),  
                    instructions: taskGr.getValue('instructions'),
					number: taskGr.getValue('number'),
					state: taskGr.getDisplayValue('state'),
					assigned_to: taskGr.getDisplayValue('assigned_to')
                });  
            }  

            output.push({  
                title: title,  
                tasks: taskArray  
            });  
        }  
    } catch (e) {  
        gs.error('Error processing system property "' + propertyName + '": ' + e.message);  
    }  

    return output;  
}
